// Read actual headers dynamically and preserve phone numbers as text.
const items = $input.all();
const rows = items.map((item, idx) => {
  const j = item.json || {};
  const getByHeader = (candidates) => {
    for (const key of Object.keys(j)) {
      const norm = key.trim().toLowerCase();
      if (candidates.includes(norm)) return j[key];
    }
    return '';
  };
  return {
    row_number: Number(j.row_number || idx + 2),
    'Lead ID': String(getByHeader(['lead id', 'lead_id', 'external_lead_id']) ?? '').trim(),
    Name: String(getByHeader(['name', 'full name', 'full_name']) ?? '').trim(),
    Phone: String(getByHeader(['phone', 'mobile', 'phone number']) ?? '').trim(),
    Service: String(getByHeader(['service', 'service interest', 'enquiry']) ?? '').trim(),
    Source: String(getByHeader(['source']) ?? 'Google Sheet').trim(),
    'Created At': String(getByHeader(['created at', 'created_at']) ?? '').trim(),
    'Calling Eligibility': String(getByHeader(['calling eligibility', 'calling_eligibility']) ?? 'ELIGIBLE').trim(),
    'Eligibility Reference': String(getByHeader(['eligibility reference', 'eligibility_reference']) ?? '').trim(),
    'Do Not Call': String(getByHeader(['do not call', 'do_not_call', 'dnc']) ?? 'FALSE').trim(),
  };
}).filter((r) => r.Phone !== '');

return [{ json: { workspaceSlug: 'digianchorz', autoEnqueueCalls: false, rows } }];
